import{_ as l,o as e,c as i,a2 as t}from"./chunks/framework.CFuv5BrO.js";const x=JSON.parse('{"title":"执行器目录","description":"Codex、Native、Connector、Browser、GUI 与 Document/Data 执行器的定位、边界和验收标准。","frontmatter":{"title":"执行器目录","description":"Codex、Native、Connector、Browser、GUI 与 Document/Data 执行器的定位、边界和验收标准。","outline":[2,3]},"headers":[],"relativePath":"architecture/executor-catalog.md","filePath":"architecture/executor-catalog.md","lastUpdated":null}'),o={name:"architecture/executor-catalog.md"};function r(n,a,c,h,u,d){return e(),i("div",null,[...a[0]||(a[0]=[t(`<p class="eyebrow">EXECUTOR CATALOG</p><h1 id="执行器目录" tabindex="-1">执行器目录 <a class="header-anchor" href="#执行器目录" aria-label="Permalink to &quot;执行器目录&quot;">​</a></h1><p class="lead">Codex、Native、Connector、Browser、GUI 和 Document/Data 各自擅长什么、何时被选择、如何验证与接管。</p><h2 id="codex-executor" tabindex="-1">Codex Executor <a class="header-anchor" href="#codex-executor" aria-label="Permalink to &quot;Codex Executor&quot;">​</a></h2><h3 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h3><p>Codex 不局限于代码，可承担调研、长文档、报告、表格、代码和多文件工作区任务；但它是执行器，不是 Hearth 的权限中心、任务数据库、记忆中心或外部副作用网关。</p><p>适合：</p><ul><li>隔离 workspace 中的长链路推理；</li><li>代码修改、测试、Issue 分流、PR 准备；</li><li>调研、归纳和结构化研究；</li><li>文档、报告、表格和数据文件生成/修改；</li><li>多步骤 Shell、文件转换和验证。</li></ul><p>不适合：</p><ul><li>直接管理邮箱、日历和通讯录；</li><li>作为长期记忆；</li><li>作为权限、审批或凭据中心；</li><li>常驻监听事件；</li><li>实时桌面和手机操作；</li><li>直接发送和发布高风险副作用。</li></ul><h3 id="task-pack-与输出契约" tabindex="-1">Task Pack 与输出契约 <a class="header-anchor" href="#task-pack-与输出契约" aria-label="Permalink to &quot;Task Pack 与输出契约&quot;">​</a></h3><p>不要给 Codex 一段无边界长提示词。输入应是 Task Pack：</p><ul><li>目标、验收标准和禁止事项；</li><li>最小必要文件、引用和产物路径；</li><li>工作区范围、可写目录和网络边界；</li><li>可用工具、预算、截止时间和取消语义；</li><li>需要的结构化输出 schema；</li><li>已知失败样本和降级方式。</li></ul><p>输出至少包括：标准化事件流、产物引用、结构化最终结果、验证结果、失败分类和可恢复性。自然语言“完成”不算完成。</p><h3 id="隔离、取消与恢复" tabindex="-1">隔离、取消与恢复 <a class="header-anchor" href="#隔离、取消与恢复" aria-label="Permalink to &quot;隔离、取消与恢复&quot;">​</a></h3><ul><li>一个 Run 一个 workspace，任务结束回收；</li><li>版本锁定 CLI/SDK，升级先跑契约测试；</li><li>最小环境变量和网络出口；</li><li>取消要终止整个进程树；</li><li>超时、崩溃和恢复要保留检查点或可重建工作区；</li><li>高风险账户和长期凭据不直接交给 Codex。</li></ul><h3 id="验收" tabindex="-1">验收 <a class="header-anchor" href="#验收" aria-label="Permalink to &quot;验收&quot;">​</a></h3><ul><li>任务包可复现；</li><li>结构化结果可解析；</li><li>产物有 diff、测试、引用或文件证据；</li><li>取消、超时和失败分类可用；</li><li>Token 和成本可归因；</li><li>不依赖自然语言“完成”。</li></ul><h2 id="native-runtime" tabindex="-1">Native Runtime <a class="header-anchor" href="#native-runtime" aria-label="Permalink to &quot;Native Runtime&quot;">​</a></h2><p>Native 是轻量、本地、可替换的通用推理层，适合短任务、低风险分类、上下文压缩和一些隐私敏感工作。它不追求替代 Codex 的长链路能力。</p><h3 id="模型阶梯" tabindex="-1">模型阶梯 <a class="header-anchor" href="#模型阶梯" aria-label="Permalink to &quot;模型阶梯&quot;">​</a></h3><ul><li>规则/脚本：完全不用模型；</li><li>小模型/本地模型：分类、抽取、短摘要；</li><li>中型模型：一般推理、结构化整理；</li><li>Codex/大模型：长链路、多文件、高价值任务。</li></ul><h3 id="工具接口与升级" tabindex="-1">工具接口与升级 <a class="header-anchor" href="#工具接口与升级" aria-label="Permalink to &quot;工具接口与升级&quot;">​</a></h3><p>Native 只通过受控工具接口读写文件、执行命令和调用 Connector。出现以下情况应升级到 Codex：</p><ul><li>任务需要大量文件协同；</li><li>需要长链路规划和反复验证；</li><li>Native 多次失败或上下文超预算；</li><li>产物质量或可靠性不达标；</li><li>需要更强的代码/文档处理能力。</li></ul><h3 id="评估" tabindex="-1">评估 <a class="header-anchor" href="#评估" aria-label="Permalink to &quot;评估&quot;">​</a></h3><p>评估不要只看“回答是否像样”，还要看任务成功率、人工分钟、Token、工具调用正确率、失败分类和升级率。小模型“省钱但反复失败”通常更贵。</p><h2 id="connector-executor" tabindex="-1">Connector Executor <a class="header-anchor" href="#connector-executor" aria-label="Permalink to &quot;Connector Executor&quot;">​</a></h2><p>Connector 把外部系统变成可审计的 <code>Source</code> 与 <code>Effect</code>，不是“把 API 钥匙交给模型”。</p><h3 id="统一模型" tabindex="-1">统一模型 <a class="header-anchor" href="#统一模型" aria-label="Permalink to &quot;统一模型&quot;">​</a></h3><ul><li>Source：读取、同步、归一化、来源、游标、限流；</li><li>Effect：类型化动作、预览、审批、outbox、幂等键、Receipt、对账；</li><li>凭据：Credential Broker 发放短期权限，执行器看不到长期密钥；</li><li>权限：按账户、资源、动作、时间和范围限定；</li><li>失败：可重试、不可重试、不确定、需人工接管分开处理。</li></ul><h3 id="邮件、日历、文档、im" tabindex="-1">邮件、日历、文档、IM <a class="header-anchor" href="#邮件、日历、文档、im" aria-label="Permalink to &quot;邮件、日历、文档、IM&quot;">​</a></h3><ul><li>邮件：只读同步、线程、联系人、附件、草稿、待审批发送；</li><li>日历：只读、时区、冲突检查、待审批写入；</li><li>文档/云盘：读取、版本、导出、待审批分享；</li><li>IM/Issue/代码托管：消息、Issue、PR、评论等 Source/Effect，高风险动作审批。</li></ul><p>Stage 2 先接一个真实只读 Connector，再逐步增加写入。不要在第一个 Connector 上同时打开所有高风险动作。</p><h3 id="限流、重试与对账" tabindex="-1">限流、重试与对账 <a class="header-anchor" href="#限流、重试与对账" aria-label="Permalink to &quot;限流、重试与对账&quot;">​</a></h3><ul><li>每次投递有幂等键；</li><li>限流和退避由系统控制，不交给模型自由重试；</li><li>不确定结果先查询/对账；</li><li>死信可查看、修复和人工重放；</li><li>撤销和权限回收要有审计。</li></ul><h2 id="browser-executor" tabindex="-1">Browser Executor <a class="header-anchor" href="#browser-executor" aria-label="Permalink to &quot;Browser Executor&quot;">​</a></h2><p>Browser 用 Playwright 操作没有 API 或 API 不足的网页，但网页内容是不可信输入。</p><h3 id="三种模式" tabindex="-1">三种模式 <a class="header-anchor" href="#三种模式" aria-label="Permalink to &quot;三种模式&quot;">​</a></h3><ol><li><strong>只读研究</strong>：打开、登录态受限、抓取、截图、来源；</li><li><strong>草稿操作</strong>：填表、准备提交但不自动发送；</li><li><strong>受控执行</strong>：在 Mandate 和审批下提交低/中风险动作。</li></ol><h3 id="执行流程" tabindex="-1">执行流程 <a class="header-anchor" href="#执行流程" aria-label="Permalink to &quot;执行流程&quot;">​</a></h3><ul><li>明确目标和允许域名；</li><li>准备隔离 profile；</li><li>观察页面和来源；</li><li>非高风险步骤自动执行；</li><li>遇到验证码、异常或高风险提交时接管；</li><li>保存截图、DOM/状态证据和来源；</li><li>验证最终状态，产生 Receipt（如有副作用）。</li></ul><h3 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to &quot;安全&quot;">​</a></h3><ul><li>页面文本不能当作系统指令；</li><li>提示词注入不能扩大权限；</li><li>登录态与长期凭据隔离；</li><li>网络出口白名单；</li><li>下载文件要验证类型和来源；</li><li>不可信页面不能直接触发付款、发布、删除或权限变更。</li></ul><h3 id="失败与接管" tabindex="-1">失败与接管 <a class="header-anchor" href="#失败与接管" aria-label="Permalink to &quot;失败与接管&quot;">​</a></h3><p>浏览器失败通常不是“再试一次”能解决。验证码、MFA、页面结构变化、登录过期和不可逆提交必须明确进入 <code>needs_human</code>，并展示用户需要做什么。</p><h2 id="gui-executor" tabindex="-1">GUI Executor <a class="header-anchor" href="#gui-executor" aria-label="Permalink to &quot;GUI Executor&quot;">​</a></h2><p>GUI 操作没有 API 的桌面软件和跨应用流程。它比 Browser 更脆弱，因此更依赖白名单、验证和接管。</p><h3 id="运行位置" tabindex="-1">运行位置 <a class="header-anchor" href="#运行位置" aria-label="Permalink to &quot;运行位置&quot;">​</a></h3><ul><li>设备 <code>agentd</code> 在目标桌面运行；</li><li>使用可访问性树、截图、键鼠、窗口和文件选择；</li><li>高风险任务在隔离虚拟桌面运行；</li><li>手机只是查看/接管入口，不是默认执行权威。</li></ul><h3 id="执行流程-1" tabindex="-1">执行流程 <a class="header-anchor" href="#执行流程-1" aria-label="Permalink to &quot;执行流程&quot;">​</a></h3><ol><li>识别目标应用和窗口；</li><li>确认能力和权限；</li><li>观察当前状态；</li><li>执行最小动作；</li><li>通过可访问性树、截图或目标状态验证；</li><li>失败则暂停、接管或回滚；</li><li>记录审计和证据。</li></ol><h3 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h3><ul><li>应用/窗口白名单；</li><li>不读取密码库；</li><li>不修改系统安全设置；</li><li>高风险动作二次确认；</li><li>不假设屏幕坐标永远稳定；</li><li>每次操作后验证状态，不只看“点击成功”。</li></ul><h3 id="失败与接管-1" tabindex="-1">失败与接管 <a class="header-anchor" href="#失败与接管-1" aria-label="Permalink to &quot;失败与接管&quot;">​</a></h3><p>GUI 必须假定会失败。用户要能暂停自动输入、接管、操作、交还或终止；系统要记录接管前后状态，避免自动流程和人工同时争抢键鼠。</p><h2 id="document-data-executor" tabindex="-1">Document/Data Executor <a class="header-anchor" href="#document-data-executor" aria-label="Permalink to &quot;Document/Data Executor&quot;">​</a></h2><p>Document/Data 让确定性工作不经过模型：解析、OCR、格式转换、表格清洗、对账、统计、图表和导入导出。</p><h3 id="管道" tabindex="-1">管道 <a class="header-anchor" href="#管道" aria-label="Permalink to &quot;管道&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入文件 → 类型识别 → 解析/OCR → 结构化中间结果</span></span>
<span class="line"><span>→ 确定性转换/计算 → 验证 → Artifact + 来源</span></span></code></pre></div><p>模型只处理真正需要语义判断的部分；重复计算、格式转换和数据校验不调用模型。</p><h3 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h3><ul><li>文档结构、页码、引用和关键字段；</li><li>表格 schema、行数、公式、抽样和对账；</li><li>输出可复现、可 diff、可回溯原文件；</li><li>大文件只提取所需片段和 artifact 引用；</li><li>原文件不被破坏，失败可回退。</li></ul><h3 id="与-codex-的分工" tabindex="-1">与 Codex 的分工 <a class="header-anchor" href="#与-codex-的分工" aria-label="Permalink to &quot;与 Codex 的分工&quot;">​</a></h3><ul><li>确定性处理：Document/Data；</li><li>需要长文档理解、写作、复杂格式和多文件协调：Codex；</li><li>判断哪个更便宜、更可靠由路由决定，不按工具偏好。</li></ul>`,65)])])}const p=l(o,[["render",r]]);export{x as __pageData,p as default};
